package com.projexa.coaching.academics.service;
import com.projexa.coaching.common.exceptions.ApiException; import com.projexa.coaching.common.tenant.TenantContextHolder; import com.projexa.coaching.academics.entity.AcademicYear; import com.projexa.coaching.academics.repository.AcademicYearRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AcademicYearService { private final AcademicYearRepository repo; public AcademicYearService(AcademicYearRepository repo){this.repo=repo;} public List<AcademicYear> list(){return repo.findAllByTenantId(TenantContextHolder.getRequired());} public AcademicYear get(UUID id){return repo.findByIdAndTenantId(id,TenantContextHolder.getRequired()).orElseThrow(()->new ApiException("NOT_FOUND","Resource not found"));} public AcademicYear create(AcademicYear item){item.setTenantId(TenantContextHolder.getRequired()); return repo.save(item);} public AcademicYear update(UUID id,AcademicYear item){AcademicYear current=get(id); copy(item,current); return repo.save(current);} public void delete(UUID id){repo.delete(get(id));} private void copy(AcademicYear s,AcademicYear t){t.setName(s.getName());t.setStartDate(s.getStartDate());t.setEndDate(s.getEndDate());t.setCurrent(s.isCurrent());t.setStatus(s.getStatus());}}